import base64
import json
import os
import shutil
import sqlite3
import subprocess
import sys
import zlib
from datetime import datetime
from pathlib import Path

PAYLOAD = ''


def is_project(path):
    return (path / 'radar.py').is_file() and (path / 'static' / 'app.js').is_file()


def locate_project():
    if len(sys.argv)>1:
        target=Path(sys.argv[1]).expanduser().resolve()
        if not is_project(target):
            raise ValueError('Wskazany folder nie zawiera radar.py oraz static/app.js')
        return target
    if is_project(Path.cwd()):
        return Path.cwd()
    candidates=[]
    for parent in [Path.home()/'Downloads',Path.home()/'Pobrane',Path(__file__).resolve().parent]:
        if not parent.is_dir():
            continue
        for file in parent.glob('**/radar.py'):
            relative=file.relative_to(parent)
            if len(relative.parts)>5 or any(part.startswith(('.', '_radar_update_backup')) for part in relative.parts):
                continue
            if is_project(file.parent) and file.parent.resolve() not in candidates:
                candidates.append(file.parent.resolve())
    if len(candidates)==1:
        return candidates[0]
    print('Podaj folder projektu z plikiem radar.py.')
    for candidate in candidates:
        print('  '+str(candidate))
    target=Path(input('Ścieżka folderu: ').strip().strip('"').strip("'")).expanduser().resolve()
    if not is_project(target):
        raise ValueError('Nie znaleziono projektu we wskazanym folderze')
    return target


def main():
    target=locate_project()
    files=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    stamp=datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backup=target/('_radar_update_backup_'+stamp)
    backup.mkdir()
    changed=[]
    database=target/'radar.sqlite3'
    if database.exists():
        with sqlite3.connect(database) as original,sqlite3.connect(backup/'radar.sqlite3') as copy:
            original.backup(copy)
    try:
        for name,content in files.items():
            path=target/name
            if path.exists():
                old=backup/name
                old.parent.mkdir(parents=True,exist_ok=True)
                shutil.copy2(path,old)
            if name=='settings.json' and path.exists():
                original=json.loads(path.read_text(encoding='utf-8'))
                defaults={s['id']:s for s in json.loads(content)['sources']}
                for source in original['sources']:
                    update=defaults.get(source['id'])
                    if update:
                        source['country_scope']='PL'
                        if source['id'] in ['crossref','bn','aiclearing','otwarte_dane']:
                            for field in ['enabled','status','note']:
                                source[field]=update[field]
                        if source['id']=='cordis':source['note']=update['note']
                content=json.dumps(original,ensure_ascii=False,indent=2)
            path.parent.mkdir(parents=True,exist_ok=True)
            temporary=path.with_name(path.name+'.radar-update-tmp')
            temporary.write_text(content,encoding='utf-8')
            os.replace(temporary,path)
            changed.append(name)
        ignore=target/'.gitignore'
        existing=ignore.read_text() if ignore.exists() else ''
        if '_radar_update_backup*/' not in existing:
            ignore.write_text(existing+'\n_radar_update_backup*/\n',encoding='utf-8')
        subprocess.run([sys.executable,str(target/'radar.py'),'init'],cwd=target,check=True)
    except Exception:
        for name in reversed(changed):
            original=backup/name
            if original.exists():shutil.copy2(original,target/name)
            else:(target/name).unlink(missing_ok=True)
        # SQLite migrations are transactional. Keep the database snapshot available for recovery.
        print('Aktualizacja przerwana. Przywrócono zmieniane pliki. Kopia bazy: '+str(backup))
        raise
    print('Zaktualizowano istniejący projekt: '+str(target))
    print('Kopia bezpieczeństwa: '+str(backup))
    print('Zatrzymaj poprzedni serwer klawiszami Ctrl+C i uruchom w folderze projektu: python3 start.py')
    print('Następnie otwórz http://localhost:8080 i odśwież stronę.')


if __name__=='__main__':
    try:
        main()
    except Exception as error:
        print('Nie udało się zastosować poprawki: '+str(error),file=sys.stderr)
        sys.exit(1)
